WITH with_latest AS (SELECT s.*, top1.web_event_duration_sec FROM sessions s JOIN LATERAL (SELECT c.duration_sec AS web_event_duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT country, COUNT(CASE WHEN device = 'tablet' THEN 1 END) AS tablet_count, COUNT(CASE WHEN browser = 'Safari' THEN 1 END) AS safari_count FROM with_latest GROUP BY country;
